/* From Uiverse.io by vinodjangid07  - Tags: form, image, file upload, file, browse */
.__UIV_SCOPE__ .file-upload-form {
  width: fit-content;
  height: fit-content;
  display: flex;
  align-items: center;
  justify-content: center;
}
.__UIV_SCOPE__ .file-upload-label input {
  display: none;
}
.__UIV_SCOPE__ .file-upload-label svg {
  height: 50px;
  fill: rgb(82, 82, 82);
  margin-bottom: 20px;
}
.__UIV_SCOPE__ .file-upload-label {
  cursor: pointer;
  background-color: #ddd;
  padding: 30px 70px;
  border-radius: 40px;
  border: 2px dashed rgb(82, 82, 82);
  box-shadow: 0px 0px 200px -50px rgba(0, 0, 0, 0.719);
}
.__UIV_SCOPE__ .file-upload-design {
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 5px;
}
.__UIV_SCOPE__ .browse-button {
  background-color: rgb(82, 82, 82);
  padding: 5px 15px;
  border-radius: 10px;
  color: white;
  transition: all 0.3s;
}
.__UIV_SCOPE__ .browse-button:hover {
  background-color: rgb(14, 14, 14);
}
